lr_recipe&lt;-recipe(diabetes~.,data = ml_training) |&gt;
  step_log(all_numeric()) |&gt; 
  step_normalize(all_numeric()) |&gt; #Centering and scaling
  step_dummy(all_nominal(), -all_outcomes())
lr_worflow&lt;-workflow() |&gt; 
